        line = re.sub ('\u2500\u2502','\u2500\u2524',line) # -|
        line = re.sub ('\u2502\u2500','\u251c',line) # |- 
        line = re.sub ('\u2524\u2500','\u253c',line) # -|-
        if strict:
            for u,a in cmap.items():
